package io.github.affonsopaulo.stremionow.ui.l10n

import androidx.compose.runtime.Composable
import androidx.compose.runtime.ReadOnlyComposable
import androidx.compose.ui.res.pluralStringResource as androidPluralStringResource
import androidx.compose.ui.res.stringResource as androidStringResource

// Android reads l10n/res as its own resources, so locale matching, plural rules and formatting
// are the platform's. androidStringId and androidPluralsId are generated by generateStrings.

@Composable
@ReadOnlyComposable
actual fun stringResource(resource: StringResource): String = androidStringResource(androidStringId(resource.key))

@Composable
@ReadOnlyComposable
actual fun stringResource(
    resource: StringResource,
    vararg formatArgs: Any,
): String = androidStringResource(androidStringId(resource.key), *formatArgs)

@Composable
@ReadOnlyComposable
actual fun pluralStringResource(
    resource: PluralsResource,
    count: Int,
): String = androidPluralStringResource(androidPluralsId(resource.key), count)

@Composable
@ReadOnlyComposable
actual fun pluralStringResource(
    resource: PluralsResource,
    count: Int,
    vararg formatArgs: Any,
): String = androidPluralStringResource(androidPluralsId(resource.key), count, *formatArgs)
